mapper.sql:
and e.status not in ('draft', 'hidden')

    and e.city_code = #{city}




            and (e.status = 'completed' or e.event_date < curdate())


            and e.status = #{status}
            and e.event_date >= curdate()




    and e.visibility = 'member'


    and e.visibility = 'public'


    and e.visibility = 'registered'


    and date_format(e.event_date, '%Y-%m') = #{month}

mapper.select:
select event_id as eventId, field_name as fieldName, value from cm_event_localized_fields where event_id in
#{eid}
and status = 'ready' and trim(value) != '' and field_name in ('title','summary','venue','address','format','audience') order by event_id, field_name, case locale when #{locale} then 0 when 'zh' then 1 when 'en' then 2 else 3 end

select event_id as eventId, language_code as languageCode from cm_event_language_codes where event_id in
#{eid}
order by event_id, language_code

select event_id as eventId, focus_order as sortOrder, value from cm_event_relationship_focuses where event_id in
#{eid}
and status = 'ready' and trim(value) != '' order by event_id, focus_order, case locale when #{locale} then 0 when 'zh' then 1 when 'en' then 2 else 3 end

select event_id as eventId, status, count(1) as cnt from cm_event_registrations where event_id in
#{eid}
group by event_id, status

select e.id, e.status, e.visibility, e.consumes_membership_quota as consumesMembershipQuota, e.city_code as cityCode, e.address_visibility as addressVisibility, e.event_date as eventDate, e.start_time as startTime, e.end_time as endTime, e.capacity, (select count(1) from cm_event_registrations r where r.event_id = e.id and r.status in ('confirmed', 'attended')) as occupiedCount, e.cover_image_url as coverImageUrl, e.created_at as createdAt, e.updated_at as updatedAt, lf.value as title from cm_events e left join cm_event_localized_fields lf on lf.event_id = e.id and lf.field_name = 'title' and lf.locale = coalesce(#{params.locale}, 'zh')
and lf.value like concat('%', #{params.keyword}, '%')
and e.status = #{params.status}
and e.city_code = #{params.city}
and e.event_date >= #{params.dateFrom}
and e.event_date <= #{params.dateTo}
order by e.created_at desc
order by e.event_date desc, e.start_time desc

select value
from cm_event_relationship_focuses
where event_id = #{eventId}
  and locale = #{locale}
  and status = 'ready'
order by focus_order

mapper.insert:
insert into cm_event_language_codes (
    event_id, language_code
) values (
    #{eventId}, #{languageCode}
)

mapper.delete:
delete lf from cm_event_agenda_item_localized_fields lf
join cm_event_agenda_items i on i.id = lf.agenda_item_id
where i.event_id = #{eventId}

mapper.insert:
insert into cm_event_agenda_items (
    id, event_id, agenda_time, sort_order, created_at, updated_at
) values (
    #{id}, #{eventId}, #{agendaTime}, #{sortOrder}, now(), now()
)

mapper.delete:
delete lf from cm_event_note_item_localized_fields lf
join cm_event_note_items i on i.id = lf.note_item_id
where i.event_id = #{eventId}

mapper.insert:
insert into cm_event_note_items (
    id, event_id, sort_order, created_at, updated_at
) values (
    #{id}, #{eventId}, #{sortOrder}, now(), now()
)

mapper.select:
select r.id, r.user_id as userId, r.event_id as eventId, r.entitlement_balance_id as entitlementBalanceId, r.status, r.requested_at as requestedAt, r.confirmed_at as confirmedAt, r.declined_at as declinedAt, r.waitlisted_at as waitlistedAt, r.cancelled_at as cancelledAt, r.attended_at as attendedAt, r.event_quota_consumed_at as eventQuotaConsumedAt, r.event_quota_released_at as eventQuotaReleasedAt, r.created_at as createdAt, r.updated_at as updatedAt, u.account_name as userAccountName, lf.value as eventTitle, e.event_date as eventDate from cm_event_registrations r join cm_events e on e.id = r.event_id left join cm_users u on u.id = r.user_id left join cm_event_localized_fields lf on lf.event_id = e.id and lf.field_name = 'title' and lf.locale = coalesce(#{params.locale}, 'zh')
and e.id = #{params.eventId}
and lf.value like concat('%', #{params.eventTitle}, '%')
and (r.user_id like concat('%', #{params.userKeyword}, '%') or u.account_name like concat('%', #{params.userKeyword}, '%'))
and r.status = #{params.status}
and r.requested_at >= #{params.dateFrom}
and r.requested_at <= #{params.dateTo}
order by r.updated_at desc
order by lf.value asc, r.requested_at desc
order by u.account_name asc, r.requested_at desc
order by r.requested_at desc
